/**
 * #873 — THE GOAL CORPUS, EVERY GATE (worker tier). Each fixture under `tests/fixtures/goals/`
 * is imported through the app's own door, generated, swept and measured against its goal. The
 * numbers are pinned as TODAY'S BASELINE: they are what the engine does now, including where it
 * does too little (a figure the top setup cannot finish), so a regression is a number that moved
 * rather than a screenshot someone has to interpret.
 *
 * The fixtures are generated by `scripts/gen-goal-fixtures.mts` (see the corpus README): the
 * relief and figure are meshes this repo builds, nothing third-party is checked in.
 */

import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { afterEach, describe, expect, it } from 'vitest';

import { tl } from './helpers/manifoldExec';
import { generate } from './helpers/engravePipeline';
import { defaultEngraveJob } from '@/engine/cnc/engrave/defaults';
import { jobTool, toSetup } from '@/engine/cnc/engrave/jobSetup';
import { chooseLayFlat } from '@/engine/cnc/engrave/goalOrientation';
import { sampleGoalHeightfield } from '@/engine/cnc/engrave/goalHeightfield';
import { goalCoverage, type CoverageMesh, type ResultTop } from '@/engine/cnc/engrave/goalCoverage';
import { goalSurfaceOffer } from '@/engine/cnc/engrave/goalFlipFindings';
import { clearTargetObjectMeshCache, readTargetObjectFile, targetObjectMesh } from '@/engine/import/targetObject';
import { placeTarget } from '@/engine/cnc/engrave/targetPlace';
import { Z1 } from '@/engine/cnc/machine';
import { createSimSession } from '@/workers/sim/session';
import type { FlatField } from '@/workers/geometry/carriedField';
import type { Tool } from '@/engine/cnc/tool';
import type { EngraveJob, EngraveTargetObject } from '@/types/engraveJob';

afterEach(() => clearTargetObjectMeshCache());

const here = (name: string): string => fileURLToPath(new URL(`../fixtures/goals/${name}`, import.meta.url));

/** The fixture read through the app's own door, as the picker does. */
async function read(name: string): Promise<Extract<Awaited<ReturnType<typeof readTargetObjectFile>>, { ok: true }>> {
  const bytes = readFileSync(here(name));
  const result = await readTargetObjectFile(new File([bytes], name), `goal-${name}`);
  if (!result.ok) throw new Error(`${name}: ${result.error}`);
  return result;
}

/** The goal object the picker builds (`readTarget`), with `position` on the blank's centre. */
function targetOf(
  read: Extract<Awaited<ReturnType<typeof readTargetObjectFile>>, { ok: true }>,
  stock: { length: number; width: number },
): EngraveTargetObject {
  return {
    id: read.id,
    name: read.name,
    format: read.format,
    sha256: read.sha256,
    data: read.data,
    size: read.size,
    position: { x: stock.length / 2, y: stock.width / 2, z: 0 },
    rotation: 0,
    enabled: true,
    role: 'goal',
  };
}

/** A pure-goal job on a blank sized to the mesh. */
function goalJob(target: EngraveTargetObject, stock: { length: number; width: number; thickness: number }): EngraveJob {
  const base = defaultEngraveJob();
  return {
    ...base,
    name: target.name,
    labels: [],
    shapes: [],
    drills: [],
    stock: { ...stock, material: 'softwood' },
    toolKey: 'flat-1.0',
    targetObject: target,
  };
}

/** The goal's triangles in the WORK frame — the same placement the sampler cuts from. */
function workMesh(target: EngraveTargetObject): CoverageMesh {
  const mesh = targetObjectMesh(target);
  const { place } = placeTarget(target, mesh);
  const positions = new Float32Array(mesh.positions.length);
  for (let i = 0; i < mesh.positions.length; i += 3) {
    const [x, y, z] = place(mesh.positions[i]!, mesh.positions[i + 1]!, mesh.positions[i + 2]!);
    positions[i] = x;
    positions[i + 1] = y;
    positions[i + 2] = z;
  }
  return { positions, indices: mesh.indices };
}

/** The swept result's top at a work XY, bilinear on the column engine's own grid. */
function resultTopOf(field: FlatField): ResultTop {
  return (x, y) => {
    const fi = (x - field.u0) / field.du;
    const fj = (y - field.v0) / field.dv;
    const i0 = Math.floor(fi);
    const j0 = Math.floor(fj);
    if (i0 < 0 || j0 < 0 || i0 + 1 >= field.nu || j0 + 1 >= field.nv) return null;
    const tx = fi - i0;
    const ty = fj - j0;
    const at = (i: number, j: number): number => field.top[j * field.nu + i]!;
    const z0 = at(i0, j0) * (1 - tx) + at(i0 + 1, j0) * tx;
    const z1 = at(i0, j0 + 1) * (1 - tx) + at(i0 + 1, j0 + 1) * tx;
    return z0 * (1 - ty) + z1 * ty;
  };
}

/** Generate, sweep and measure one fixture; the numbers the baseline pins. */
async function runFixture(
  name: string,
  stock: { length: number; width: number; thickness: number },
): Promise<{
  read: Awaited<ReturnType<typeof read>>;
  ok: boolean;
  stage: string;
  seconds: number | null;
  loadOk: boolean;
  fraction: number;
  facingAway: number;
  shadowed: number;
  missed: number;
}> {
  const imported = await read(name);
  const target = targetOf(imported, stock);
  const job = goalJob(target, stock);
  const g = await generate(tl, job);
  let fraction = 0;
  let facingAway = 0;
  let shadowed = 0;
  let missed = 0;
  let loadOk = false;
  if (g.ok && g.nc !== null) {
    const tool = jobTool(job);
    if (tool === null) throw new Error(`${job.toolKey} is not in the tool library`);
    const session = createSimSession(tl);
    try {
      const load = session.load(g.nc, toSetup(job, Z1), tool, Z1.id);
      loadOk = load.ok;
      if (load.ok) {
        // The measure samples the goal FINELY (0.1 mm): a coarse raster's own cell-max bias would
        // read as a miss on every slope. The result side is the column grid's own pitch.
        const goal = sampleGoalHeightfield(target, { stockTopZ: 0, pitchMm: 0.1 });
        const field = load.flatField ?? null;
        // 0.1 mm is the column grid's own pitch — the oracle's spatial band (floored at 0.05):
        // a face cut to the CAM's resolution is reached; stock left standing on a steep flank is
        // not, and that is a true statement about the cutter, not a measurement artefact.
        const c = goalCoverage(workMesh(target), goal, field === null ? null : resultTopOf(field), {
          reachedMm: 0.1,
        });
        fraction = c.fraction;
        facingAway = c.facingAwayAreaMm2;
        shadowed = c.shadowedAreaMm2;
        missed = c.missedAreaMm2;
      }
    } finally {
      session.dispose();
    }
  }
  return {
    read: imported,
    ok: g.ok,
    stage: g.stage,
    seconds: g.cam?.estimatedSeconds ?? null,
    loadOk,
    fraction,
    facingAway,
    shadowed,
    missed,
  };
}

describe('#873 the goal corpus: the import states what the file is', () => {
  it('every fixture imports, and its stated size is its own bounding box', async () => {
    const relief = await read('relief-plate.stl');
    expect(relief.size.x).toBeCloseTo(40, 1);
    expect(relief.size.y).toBeCloseTo(30, 1);
    expect(relief.size.z).toBeCloseTo(7, 1); // a 4 mm plate and its 3 mm raised boss
    expect(relief.format).toBe('stl');

    const obj = await read('relief-plate.obj');
    expect(obj.format).toBe('obj');
    expect(obj.size.x).toBeCloseTo(40, 1);

    const sphere3mf = await read('near-sphere.3mf');
    expect(sphere3mf.format).toBe('3mf');
    expect(sphere3mf.size.x).toBeCloseTo(30, 1);

    const figure = await read('figure.stl');
    expect(figure.size.y).toBeGreaterThan(20);
    expect(figure.size.z).toBeGreaterThan(25); // it stands: an underside this job must reach
  });

  it('the inches OBJ states its unit, and its size is read in millimetres', async () => {
    const inches = await read('figure-inches.obj');
    expect(inches.note).toBeDefined();
    expect(inches.note!.toLowerCase()).toContain('inch');
    // The file's numbers are the figure ÷ 25.4; the STATED size is millimetres.
    const mm = await read('figure.stl');
    expect(inches.size.x).toBeCloseTo(mm.size.x, 0);
    expect(inches.size.z).toBeCloseTo(mm.size.z, 0);
  });

  it('the part that does not lie flat is offered the turn', async () => {
    const bar = await read('tilted-bar.stl');
    const target = targetOf(bar, { length: 80, width: 50 });
    const flat = chooseLayFlat(target, { x: 70, y: 40 });
    expect(flat.changes).toBe(true);
    expect(flat.depthMm).toBeLessThan(flat.currentDepthMm);
  });

  it('the sphere already lies as flat as it gets', async () => {
    const sphere = await read('near-sphere.stl');
    const target = targetOf(sphere, { length: 60, width: 50 });
    expect(chooseLayFlat(target, { x: 50, y: 40 }).changes).toBe(false);
  });
});

describe('#873/#872 the plan each shape gets, when the top setup cannot finish it', () => {
  it('a sphere: two setups reach the goal — the flip is the plan', async () => {
    const imported = await read('near-sphere.stl');
    const target = targetOf(imported, { length: 60, width: 50 });
    const job = goalJob(target, { length: 60, width: 50, thickness: 32 });
    const offer = goalSurfaceOffer(job, target);
    expect(offer).not.toBeNull();
    expect(offer!.plan.sides.map((s) => s.faceUp)).toEqual(['top', 'bottom']);
    expect(offer!.plan.reachedFraction).toBeGreaterThanOrEqual(0.95);
  });

  it('a figure: the sides it needs, stopping at the target — top, bottom, and one more', async () => {
    const imported = await read('figure.stl');
    const target = targetOf(imported, { length: 100, width: 60 });
    const job = goalJob(target, { length: 100, width: 60, thickness: 40 });
    const offer = goalSurfaceOffer(job, target);
    expect(offer).not.toBeNull();
    // Today the figure's third side is a real gain (surfaces shadowed from both the top and the
    // bottom, under the body); the plan says so rather than calling a 91 % plan finished.
    expect(offer!.plan.sides.length).toBeGreaterThanOrEqual(2);
    expect(offer!.plan.reachedFraction).toBeGreaterThanOrEqual(0.95);
    expect(offer!.plan.stopped).toBe('target-reached');
  });

  it('a relief: no plan at all — what remains is the stock’s own flat face', async () => {
    const imported = await read('relief-plate.stl');
    const target = targetOf(imported, { length: 80, width: 50 });
    const job = goalJob(target, { length: 80, width: 50, thickness: 20 });
    const offer = goalSurfaceOffer(job, target);
    expect(offer).not.toBeNull();
    expect(offer!.plan.sides).toHaveLength(1);
    expect(offer!.plan.stopped).toBe('only-flat-faces-remain');
  });
});

describe('#909 the goal corpus: the plan never cuts into the part', () => {
  // The oracle compares the SIMULATION with the PLAN; a plan that gouges the goal passes it. Every
  // fixture therefore generates with the plan judged against the goal's own surface (the roughing
  // clamped over the cutter's whole footprint): an over-cut refuses Generate, so this pins the
  // corpus against that regression, and names the check rather than only `ok`.
  for (const [name, stock] of [
    ['relief-plate.stl', { length: 80, width: 50, thickness: 20 }],
    ['near-sphere.stl', { length: 60, width: 50, thickness: 32 }],
    ['figure.stl', { length: 100, width: 60, thickness: 40 }],
  ] as const) {
    // #1003 landed: the seam carries the stock bottom, every op's depth is capped at it, and the
    // clipped millimetres are stated — figure.stl (41.337 mm on a 40 mm stock) no longer frees
    // through the blank. The other two fixtures sit inside their stock and are unaffected.
    it(`${name}: no cell of the plan reaches below the goal`, async () => {
      const imported = await read(name);
      const target = targetOf(imported, { length: stock.length, width: stock.width });
      const job = goalJob(target, stock);
      const g = await generate(tl, job);
      expect(g.ok, g.errors.map((e) => e.message).join('; ')).toBe(true);
      expect(g.findings.some((f) => f.code === 'goal-overcut')).toBe(false);
    }, 240_000);
  }

  // #945 — the centred, unrotated placement above never exercised a steep raster-column pair: the
  // figure's own geometry at THAT placement happens not to put a near-vertical wall across two
  // adjacent 0.1 mm finish columns. j29's placement (the stick-scale elephant job's own rotation
  // and scale, laid on a 36 × 36 × 100 mm stick) does — this is the placement #945's cut-into was
  // first measured at (`goal_check.py` and #924's `checkGoalCutInto` independently agreeing, ~8
  // cells / up to ~1.3 mm), with a ball tool (the goal CAM's normal finishing cutter; `flat-1.0`
  // above never exercises `ballRise`, so it would not catch this class at all).
  it('figure.stl at j29’s placement, a ball tool: no cell of the plan reaches below the goal (#945)', async () => {
    const imported = await read('figure.stl');
    const stock = { length: 36, width: 100, thickness: 36 };
    const target: EngraveTargetObject = {
      id: imported.id,
      name: imported.name,
      format: imported.format,
      sha256: imported.sha256,
      data: imported.data,
      size: imported.size,
      position: { x: stock.length / 2, y: 50, z: 0 },
      rotation: 90,
      enabled: true,
      role: 'goal',
      scale: { x: 0.6533, y: 0.6533, z: 0.6533 },
    };
    // Makera's 6×2×30.5 mm Ball Nose Engraving bit — the cutter the elephant job's own toolKey
    // names (`inv:lib-161032205031`), handed in directly (`job.tool` wins over the registry, #305
    // design point 2) so this test needs no location document.
    const ballTool: Tool = {
      number: 1,
      id: '161032205031',
      name: '6*2*30.5mm Ball Nose Engraving',
      typeText: 'Ball Nose Engraving',
      shape: 'ball',
      handleDiameter: 6,
      tipDiameter: 2,
      diameter: 6,
      cornerRadius: 1,
      angle: null,
      halfAngle: null,
      fluteLength: 30.5,
      shoulderLength: 30.5,
      stickout: null,
      centreCutting: null,
    };
    const base = defaultEngraveJob();
    const job: EngraveJob = {
      ...base,
      name: target.name,
      labels: [],
      shapes: [],
      drills: [],
      stock: { ...stock, material: 'hardwood' },
      toolKey: 'user:945-ball-30-5',
      tool: ballTool,
      targetObject: target,
    };
    const g = await generate(tl, job);
    expect(g.ok, g.errors.map((e) => e.message).join('; ')).toBe(true);
    expect(g.findings.some((f) => f.code === 'goal-overcut')).toBe(false);
  }, 240_000);
});

describe('#949 an oversized goal is refused at the CAM, not clipped along the jaws', () => {
  // #1003 landed: the oversize-XY refusal runs on the model path as a job finding before
  // planning, with the same sentence the old path stated.
  it('a figure larger than its blank is refused, and the sentence names the overhang', async () => {
    // The figure is ~34 mm tall and wider than this blank on both axes: the exact shape of the
    // goalTransform e2e's case (a 75 mm goal on a 43 × 32 blank), small enough for a unit test.
    const imported = await read('figure.stl');
    const stock = { length: 20, width: 20, thickness: 10 };
    const target = targetOf(imported, stock);
    const job = goalJob(target, stock);
    const g = await generate(tl, job);
    expect(g.ok, 'the CAM must refuse, not clip').toBe(false);
    expect(g.stage).toBe('cam');
    const message = g.errors.map((e) => e.message).join(' ');
    expect(message).toContain('larger than the blank');
    expect(message).toMatch(/\d+(?:\.\d+)? mm past the (left|right|front|back) edge/);
    // The refusal names the fixes, so the row's own advice and the CAM's cannot diverge.
    expect(message).toContain('Fit to the stock');
  });

  // #1003 landed: a fitting goal generates (see above).
  it('the same figure on a blank that holds it still generates — a fitting goal is untouched', async () => {
    const imported = await read('figure.stl');
    const size = imported.size;
    const stock = { length: size.x + 4, width: size.y + 4, thickness: 20 };
    const g = await generate(tl, goalJob(targetOf(imported, stock), stock));
    expect(g.ok, JSON.stringify(g.errors)).toBe(true);
  });
});

describe('#873 the goal corpus: generated, swept, and measured against the goal', () => {
  // THE BASELINE, measured 2026-11-01 on main + manifold 3.5.4 with the recommendation's own
  // cutter (`flat-1.0`): the coverage fraction and the cycle estimate are pinned as NUMBERS, so a
  // regression in tool choice, the CAM or the estimate is caught as a figure that moved.
  //
  // THE SIMULATED fractions are LOW ON PURPOSE and stay so until #869 lands: a 1 mm flat terraces
  // steep flanks far outside the 0.1 mm tolerance, so the swept surface reproduces ~13 % of a
  // sphere where #872's plan reaches ~50 % of it GEOMETRICALLY (100 % with the flip). #869 (the
  // rough-plus-finish cutter pairing) is the step that has to lift these numbers; until then this
  // is today's honest baseline, and the plan's geometric reach is pinned in the describe below.
  // #966 triage — #1007: the model path attaches no surface/goal-check report.
  it('the relief: about a quarter of the surface — the top and the dome; the flat back faces away', async () => {
    const r = await runFixture('relief-plate.stl', { length: 80, width: 50, thickness: 20 });
    expect(r.ok).toBe(true);
    expect(r.stage).toBe('done');
    expect(r.loadOk).toBe(true);
    // #1007 — THE MODEL ENGINE'S OWN MEASURE (measured 0.6178344 at the #1007 rebase): the old
    // 1 mm-flat terracing is gone, so far more of the surface is reached. Re-pinned with the cause.
    expect(r.fraction).toBeCloseTo(0.6178, 2);
    expect(r.seconds).toBeLessThan(9_000); // today: 7 948 s
  }, 240_000);

  // #966 triage — #1007: see above.
  it('the near-sphere: the lower half faces away, and a 1 mm flat cannot hug the flanks', async () => {
    const r = await runFixture('near-sphere.stl', { length: 60, width: 50, thickness: 32 });
    expect(r.ok).toBe(true);
    expect(r.loadOk).toBe(true);
    // #1007 — the model engine's own measure (0.2673667 at the #1007 rebase), re-pinned with the cause.
    expect(r.fraction).toBeCloseTo(0.2674, 2);
    expect(r.facingAway).toBeGreaterThan(0);
    expect(r.seconds).toBeLessThan(51_000); // today: 49 076 s
  }, 240_000);

  // #966 triage — #1007: see above.
  it('the figure: the top setup leaves most of the surface unreached — the case #872 answers', async () => {
    const r = await runFixture('figure.stl', { length: 100, width: 60, thickness: 40 });
    expect(r.ok).toBe(true);
    expect(r.loadOk).toBe(true);
    expect(r.fraction).toBeCloseTo(0.205, 2); // today: 0.2055 on 1003-stock-bottom (#1003 landed: the contour frees at the stock bottom)
    // Some of the unreached area faces away (legs, belly, tail underside) and some is shadowed.
    expect(r.facingAway).toBeGreaterThan(0);
    expect(r.seconds).toBeLessThan(97_000); // today: 92 828 s
  }, 300_000);
});
